// standard normal curve with shaded areas: rejection regions (crit) and/or the p-value area beyond stat
function bell(o){const pdf=ST.normPdf,area=(a,b,c)=>{const pts=[[a,0]];for(let i=0;i<=40;i++){const x=a+(b-a)*i/40;pts.push([x,pdf(x)])}pts.push([b,0]);return {pts,c}};
  const areas=[];
  if(o.crit){if(o.tails!=='right')areas.push(area(-4,-o.crit,'--warn'));if(o.tails!=='left')areas.push(area(o.crit,4,'--warn'))}
  if(o.stat!=null){if(o.tails==='left')areas.push(area(-4,Math.min(o.stat,4),'--credit'));else if(o.tails==='right')areas.push(area(Math.max(o.stat,-4),4,'--credit'));else{const s=Math.abs(o.stat);areas.push(area(-4,-Math.min(s,4),'--credit'));areas.push(area(Math.min(s,4),4,'--credit'))}}
  const vx=[];if(o.stat!=null)vx.push({x:o.stat,l:o.sl||'t = '+r2(o.stat),c:'--credit',ly:0.3});if(o.crit){if(o.tails!=='right')vx.push({x:-o.crit,l:'−'+r2(o.crit),c:'--warn',dash:true});if(o.tails!=='left')vx.push({x:o.crit,l:'+'+r2(o.crit),c:'--warn',dash:true})}
  return {xmin:-4,xmax:4,ymax:0.45,xl:o.xl||'standardized value',yl:' ',curves:[{f:pdf,c:'--ink',l:''}],areas,vx,alt:'Normal curve'}}
const scatterSpec=(pts,o={})=>({xmin:o.xmin||0,xmax:o.xmax||10,ymin:o.ymin||0,ymax:o.ymax||10,xl:o.xl||'X',yl:o.yl||'Y',dots:pts.map(p=>[p[0],p[1],p[2]||'--debit']),lines:o.lines||[],curves:o.curves||[],alt:o.alt||'Scatter plot'});
// fixed pseudo-random points for the static figures (same picture every time)
const FX=(()=>{let s=7;const u=()=>{s=(s*16807)%2147483647;return s/2147483647};const z=()=>{const a=u()||1e-9,b=u();return Math.sqrt(-2*Math.log(a))*Math.cos(2*Math.PI*b)};return {u,z}})();
const RES=(()=>{const mk=f=>Array.from({length:60},(_,i)=>{const x=0.3+i*9.4/59;return [x,f(x,FX.z())]});
  return {good:mk((x,z)=>z*1.2),curve:mk((x,z)=>0.45*(x-5)*(x-5)-3.2+z*0.6),cone:mk((x,z)=>z*(0.15+0.42*x)),run:mk((x,z)=>2.6*Math.sin(x*1.15)+z*0.35),out:mk((x,z)=>z*1.0).map((p,i)=>i===44?[p[0],8.5]:p)}})();
const resFig=(k,cap)=>FIG(scatterSpec(RES[k],{xmin:0,xmax:10,ymin:-10,ymax:10,xl:'predicted value (or X)',yl:'residual',lines:[{x1:0,y1:0,x2:10,y2:0,c:'--muted',dash:true,w:1.2}]}),cap);
