/* ---------- exercises ---------- */
const r3=x=>Math.round(x*1000)/1000;
const g3=x=>fmt(r3(x));
const tcrit=df=>{let lo=0,hi=50;const tp2=(t,d)=>{const x=d/(d+t*t);// regularized incomplete beta I_x(d/2,1/2) by continued fraction
  const a=d/2,b=0.5,lg=z=>{const c=[76.18009172947146,-86.50532032941677,24.01409824083091,-1.231739572450155,0.1208650973866179e-2,-0.5395239384953e-5];let y=z,t=z+5.5;t-=(z+0.5)*Math.log(t);let s=1.000000000190015;for(const q of c)s+=q/++y;return -t+Math.log(2.5066282746310005*s/z)};
  const cf=(a,b,x)=>{let qab=a+b,qap=a+1,qam=a-1,c=1,dd=1-qab*x/qap;if(Math.abs(dd)<1e-30)dd=1e-30;dd=1/dd;let h=dd;for(let m=1;m<=200;m++){const m2=2*m;let aa=m*(b-m)*x/((qam+m2)*(a+m2));dd=1+aa*dd;if(Math.abs(dd)<1e-30)dd=1e-30;c=1+aa/c;if(Math.abs(c)<1e-30)c=1e-30;dd=1/dd;h*=dd*c;aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));dd=1+aa*dd;if(Math.abs(dd)<1e-30)dd=1e-30;c=1+aa/c;if(Math.abs(c)<1e-30)c=1e-30;dd=1/dd;const del=dd*c;h*=del;if(Math.abs(del-1)<3e-12)break}return h};
  const bt=Math.exp(lg(a+b)-lg(a)-lg(b)+a*Math.log(x)+b*Math.log(1-x));return x<(a+1)/(a+b+2)?bt*cf(a,b,x)/a:1-bt*cf(b,a,1-x)/b};
  for(let i=0;i<80;i++){const m=(lo+hi)/2;if(tp2(m,df)>0.05)lo=m;else hi=m}return (lo+hi)/2};
