{id:'x-t9-sortpca',topic:'t9',type:'sort',src:'practice',title:'PCA: which step uses it?',q:'Sort each tool or rule into its step of the PCA.',cats:['Assumptions (step 1)','Relevance (step 2)','Variables vs components (step 3)','Number of components (steps 4–5)','Interpretation (step 6)'],
 items:[['At least 5 cases per variable','Assumptions (step 1)'],['All variables describe the same concept','Assumptions (step 1)'],['Correlations of at least 0.3 in absolute value','Relevance (step 2)'],['Communalities ≥ 0.5','Variables vs components (step 3)'],['Eigenvalue > 1 (Kaiser)','Number of components (steps 4–5)'],['Cumulative % of variance (often 80%)','Number of components (steps 4–5)'],['Rotated component matrix: |loading| > 0.6','Interpretation (step 6)'],['Sign of the loadings: opposition','Interpretation (step 6)']]}
