/* ---------- mock exams ---------- */
const MQ=(id,topic,pts,q,o,a,solution)=>({id,topic,type:'mcq',pts,q,o,a,solution});
const MP=(q,pts,o,a,topic)=>Object.assign({type:'mcq',q,pts,o,a},topic?{topic}:{});
const MN=(q,pts,answer,tol,topic)=>Object.assign({type:'numeric',q,pts,answer,tol},topic?{topic}:{});
const MW=(id,topic,pts,q,rubric,solution,lines=6)=>({id,topic,type:'written',pts,q,rubric,solution,lines});
const pv=p=>p<0.001?'< .001':p.toFixed(3);
const MOCK_INTRO=`<div class="panel"><h4>Instructions (as in the final exam)</h4><ul>
<li>2 hours. Non-programmable calculator allowed. If the significance level is not given, assume α = 5%.</li>
<li>Explain which number you read and what it means: “yes” or “no” without explanation earns nothing. One or two lines are enough.</li>
<li>Multiple-choice and numeric parts are marked automatically; written answers are marked by you after hand-in, with the official-style grid.</li>
<li>All tables and plots come from simulated datasets built for this site: every number is consistent with the others.</li></ul></div>`;
const MCALC='Non-programmable calculator (2022 and 2023 exam headers).';
const qual=a=>a<0.5?'low':a<0.6?'limited':a<0.7?'medium':a<0.8?'good':a<0.9?'very good':'excellent (or too good to be true)';

/* ===== Mock 1 ===== */
const M1=EK.m1p1,P1=M1.b,pred1=P1['(Constant)']+P1.Seats*50+P1.Footfall*20+P1.EspressoPrice*2.5+P1.Terrace*1+P1.Competitors*3;
const M1_S=[
{title:'Problem 1 · Coffee shops (9 points)',intro:`<p>You want to explain the <b>monthly sales</b> (k€) of 120 coffee shops. Predictors: <b>Seats</b> (number of seats), <b>Footfall</b> (hundreds of passers-by per day), <b>EspressoPrice</b> (€), <b>Terrace</b> (1 = terrace, 0 = no terrace), <b>Competitors</b> (number of coffee shops within 200 m).</p>${ECO.m1p1.sum}${ECO.m1p1.anova}${ECO.m1p1.coef}${ECO.m1p1.resid}${ECO.m1p1.pp}`,items:[
 MQ('a1','t5',0.5,'1) What can be said about the global quality of this model?',[`Very good: the adjusted R² is ${M1.adj}; the model explains ${(M1.adj*100).toFixed(1)}% of the variation in sales, taking into account n and the number of variables`,`Excellent: R = ${Math.sqrt(M1.R2).toFixed(3)}`,'Low: the standard error of the estimate is above 10','We cannot say: the F test is needed'],0,`<p>With several predictors read the <b>adjusted R²</b> (${M1.adj}): ${qual(M1.adj)} on the slides’ scale.</p>`),
 {id:'a2',topic:'t7',type:'case',pts:1,title:'2) Global significance',q:'<p>Is the model globally significant? Name the test, state H0 and H1, conclude.</p>',parts:[
  MP('Test and hypotheses',0.5,['F test: H0: β1 = β2 = β3 = β4 = β5 = 0; H1: at least one βj ≠ 0','t test: H0: β1 = 0; H1: β1 ≠ 0','F test: H0: the model has an effect; H1: it has no effect','Chi² test: H0: independence'],0),
  MP('Conclusion',0.5,['Sig. < .001 < 0.05: reject H0, at least one variable influences sales','Sig. > 0.05: fail to reject H0','F = 172 is too large: the model is invalid','R² proves the significance'],0)],
  solution:`<p>F = ${M1.F}, Sig. &lt; .001: at a 5% level, at least one of the five variables has an effect on monthly sales. It does not mean the model is perfect.</p>`},
 MW('a3','t5',1,`<p>3) Interpret the coefficient of <b>Footfall</b> (${P1.Footfall}).</p>`,[{c:'If footfall increases by one unit (100 passers-by per day), monthly sales increase by about 2.05 k€ (≈ 2 051 €)',pts:0.5},{c:'… on average, everything else remaining the same (and the variable is significant: Sig. < .001)',pts:0.5}],`<p>If footfall increases by one unit, i.e. 100 more passers-by per day, monthly sales increase on average by ${P1.Footfall} k€ (about ${Math.round(P1.Footfall*1000)} €), everything else remaining the same. The effect is significant (Sig. &lt; .001).</p>`,4),
 MW('a4','t8',1,`<p>4) Interpret the coefficient of <b>Terrace</b> (${P1.Terrace}).</p>`,[{c:'Terrace is a dummy: the comparison is with coffee shops without a terrace (reference group)',pts:0.5},{c:'A coffee shop with a terrace sells about 10.5 k€ more per month, everything else the same; significant (Sig. < .001)',pts:0.5}],`<p>Terrace is a dummy variable (reference: no terrace). Compared with a coffee shop without a terrace, a coffee shop with a terrace has monthly sales ${P1.Terrace} k€ higher on average, everything else remaining the same; the effect is significant.</p>`,4),
 {id:'a5',topic:'t7',type:'case',pts:1,title:'5) Competitors',q:'<p>Does the number of competitors have a significant effect on sales? Name the test, state H0 and H1, conclude.</p>',parts:[
  MP('Test and hypotheses',0.5,['t test of the coefficient: H0: β5 = 0; H1: β5 ≠ 0','F test: H0: all β = 0','Chi² test: H0: independence','t test: H0: β5 ≠ 0; H1: β5 = 0'],0),
  MP('Conclusion',0.5,[`Sig. = ${pv(M1.p.Competitors)} > 0.05: fail to reject H0, no significant effect at 5% (we do not interpret −0.949)`,`Sig. = ${pv(M1.p.Competitors)}: each competitor reduces sales by 0.949 k€`,'Significant because the coefficient is negative','Significant because the VIF is below 5'],0)],
  solution:`<p>p = ${pv(M1.p.Competitors)} ≥ 0.05 (“not very significant” on the slides’ scale): no significant effect at 5%; the 95% CI [${M1.lo.Competitors}; ${M1.hi.Competitors}] contains 0.</p>`},
 MQ('a6','t7',1,'6) Interpret the 95% confidence interval of Seats.',[`We are 95% confident that one more seat increases monthly sales by between ${M1.lo.Seats} and ${M1.hi.Seats} k€, everything else remaining the same`,`95% of the coffee shops have between ${M1.lo.Seats} and ${M1.hi.Seats} seats`,`There is a 95% probability that b = ${P1.Seats}`,`Seats explain between ${M1.lo.Seats}% and ${M1.hi.Seats}% of sales`],0,'<p>Interval for the effect β of one more unit of the variable.</p>'),
 MQ('a7','t5',0.5,`7) Interpret the standard error of the estimate (${M1.syx}).`,[`The average distance between observed and predicted monthly sales is about ${M1.syx} k€`,`${M1.syx}% of sales are not explained`,'The standard deviation of the number of seats','The error of each coffee shop is exactly 11.4 k€'],0,'<p>SYX = √(SSE/(n − k − 1)): average dispersion around the regression line, in k€.</p>'),
 MW('a8','t8',1,'<p>8) Define multicollinearity. Do you detect a problem of multicollinearity in this model? Explain.</p>',[{c:'Definition: two or more independent variables are strongly correlated (redundant information)',pts:0.5},{c:'No problem: all VIF are below 5 (the highest is about 1.09)',pts:0.5}],`<p>Multicollinearity occurs when several independent variables are highly correlated. All VIF are below 5 (max ${Math.max(...Object.values(M1.vif).filter(Boolean))}): no multicollinearity detected.</p>`,4),
 MQ('a9','t6',1,'9) Is there an obvious problem of non-normality of the residuals? Which plot do you read?',['No: on the normal P-P plot the points stay close to the diagonal','Yes: the residual plot is centred on 0','Yes: the predictors are not normally distributed','We cannot know without a Shapiro-Wilk test on each X'],0,'<p>Normality concerns the residuals; read the P-P plot (or the histogram of residuals). A problematic plot would curve away from the diagonal (S shape).</p>'),
 MN(`10) Predict the monthly sales (k€) of a coffee shop with 50 seats, a footfall of 2 000 passers-by per day, an espresso at 2.50 €, a terrace and 3 competitors (all values inside the data range).`,1,+pred1.toFixed(2),0.15,'t5')]},
{title:'Problem 2 · Loyalty card (4 points)',intro:`<p>A retailer studies 400 customers: gender, loyalty card (yes/no), basket (€) and age.</p>${ECO.m1p2.cross}${ECO.m1p2.chi}${ECO.m1p2.group}${ECO.m1p2.indep}${ECO.m1p2.corr}${ECO.m1p2.one}`,items:[
 {id:'b1',topic:'t4',type:'case',pts:1,title:'1) Gender and loyalty card',q:'<p>Are gender and having a loyalty card independent?</p>',parts:[
  MP('Test and hypotheses',0.5,['Chi² test: H0: gender and card are independent; H1: they are dependent','Pearson correlation: H0: r = 0','Two-sample t-test: H0: μmen = μwomen','Binomial test: H0: π = 0.5'],0),
  MP('Conclusion',0.5,[`p = ${pv(EK.m1p2.chiP)} > 0.05: fail to reject independence; no evidence that card ownership depends on gender`,`p = ${pv(EK.m1p2.chiP)}: the variables are dependent`,'Fisher’s exact test must be read','The variables are proven independent'],0)],
  solution:`<p>No cell has an expected count below 5, so the Pearson chi-square is readable: p = ${pv(EK.m1p2.chiP)} ≥ 0.05 → not enough evidence of dependence.</p>`},
 {id:'b2',topic:'t4',type:'case',pts:1,title:'2) Basket and loyalty card',q:'<p>Is the mean basket the same for card holders and non-holders?</p>',parts:[
  MP('Which line do you read?',0.5,['Line 2 (equal variances not assumed): Levene’s Sig. < 0.05','Line 1: Levene’s Sig. < 0.05','Line 1: always','Neither: use a paired test'],0),
  MP('Conclusion',0.5,[`Welch p ${pv(EK.m1p2.welchP)} < 0.05: the mean basket differs; card holders spend more (≈ ${EK.m1p2.m1.toFixed(1)} € vs ${EK.m1p2.m2.toFixed(1)} €)`,'No difference: the means are close','The variances are equal','The test needs n > 1000'],0)],
  solution:`<p>Levene Sig. &lt; .001 → variances differ → Welch line; its two-sided p &lt; .001 → reject equality of means.</p>`},
 MQ('b3','t4',1,'3) Is there a significant correlation between age and basket?',[`No: r = ${EK.m1p2.r.toFixed(3)} (very weak) and Sig. = ${pv(EK.m1p2.rP)} > 0.05`,'Yes: the correlation is negative','Yes: N = 400 is large','We need a chi² test'],0,'<p>Pearson correlation test: H0 no linear correlation; p ≥ 0.05 → fail to reject.</p>'),
 {id:'b4',topic:'t4',type:'case',pts:1,title:'4) Mean basket equal to 45 €?',q:'<p>Your manager says the mean basket of all customers is 45 €.</p>',parts:[
  MP('Test and hypotheses',0.5,['One sample t-test: H0: μ = 45; H1: μ ≠ 45','Two-sample t-test: H0: μ1 = μ2','Binomial test: H0: π = 45%','Paired t-test'],0),
  MN('Two-sided p-value you read',0.5,+EK.m1p2.oneP.toFixed(3),0.002)],
  solution:`<p>p = ${pv(EK.m1p2.oneP)} ≥ 0.05: we cannot reject that the mean basket in the population is 45 €.</p>`}]},
{title:'Problem 3 · E-bikes (3 points)',intro:`<p>A model predicts the <b>price</b> (€) of 60 e-bikes with <b>Battery</b> (Wh), <b>Weight</b> (kg), <b>Brand</b> (1 = Alpha, 2 = Beta, 3 = Gamma) and <b>Cargo</b> (1 = cargo bike, 0 = not). A cell has been replaced by “AAAA”.</p>${ECO.m1p3.anova}${ECO.m1p3.coef}`,items:[
 MN('1) Determine the value of AAAA (no formula needed).',1,+EK.m1p3.SSE.toFixed(3),1,'t5'),
 MQ('c2','t8',1,'2) What can be said about the coefficient of Brand?',['It cannot be used: Brand is qualitative and coded 1, 2, 3; two dummy variables (with a reference brand) are needed','Gamma bikes are 2 × 96.8 € cheaper than Beta bikes','Brand is significant, so the coding is fine','Brand should be removed because its VIF is above 5'],0,'<p>2025 final: a qualitative variable coded with numbers makes the coefficient meaningless.</p>'),
 MW('c3','t8',1,`<p>3) Interpret the coefficient of Cargo (${EK.m1p3.b.Cargo}).</p>`,[{c:'Comparison with non-cargo bikes (reference group)',pts:0.5},{c:'A cargo bike costs about 386 € more, everything else the same; significant (Sig. < .001)',pts:0.5}],`<p>Compared with a non-cargo e-bike, a cargo e-bike is ${EK.m1p3.b.Cargo} € more expensive on average, everything else remaining the same (significant).</p>`,4)]},
{title:'Problem 4 · Leisure habits (4 points)',intro:`<p>500 respondents rate how often they use or practise 8 activities (0–10). A PCA was run; assumptions are assumed valid.</p>${ECO.m1p4.tv}${ECO.m1p4.cm}${ECO.m1p4.rc}${ECO.m1p4.plot}`,items:[
 {id:'d1',topic:'t9',type:'case',pts:1,title:'1) Number of components',q:'',parts:[MN('How many components do you keep?',0.5,EK.m1p4.keep,0),MP('Which rule?',0.5,['Kaiser: eigenvalue above 1','Keep all components','Eigenvalue above 0.5','Loadings above 0.6'],0)],
  solution:`<p>Three eigenvalues are above 1 (${EK.m1p4.values.slice(0,3).join(', ')}); together they explain ${EK.m1p4.cum[2]}% of the variance.</p>`},
 MW('d2','t9',1.5,'<p>2) Interpret carefully the first two components: which variables, with which sign, and give each a name.</p>',[{c:'Component 1: Football, Gym, Running (positive loadings ≈ 0.9)',pts:0.5},{c:'Component 2: Netflix, DisneyPlus, Cinema (positive)',pts:0.5},{c:'Meaningful names (e.g. “sport” and “screen entertainment”)',pts:0.5}],'<p>Component 1 groups football, gym and running (loadings ≈ 0.88–0.91): <b>sport</b>. Component 2 groups Netflix, Disney+ and cinema: <b>screen entertainment</b>. (Component 3: books and podcasts.)</p>',5),
 MQ('d3','t9',0.5,'3) Can we link watching Netflix and going to the gym?',['No: they belong to different components','Yes: both have high loadings','Yes, negatively','Only with Kaiser’s rule'],0,'<p>Different components → no link can be concluded.</p>'),
 MN('4) Which % of the total variance do the kept components explain together?',1,+EK.m1p4.cum[EK.m1p4.keep-1].toFixed(3),0.05,'t9')]}];

/* ===== Mock 2 ===== */
const M2=EK.m2p1,P2=M2.b,M23=EK.m2p3;
const M2_S=[
{title:'Problem 1 · Hotel prices (10 points)',intro:`<p>Price per night (€) of 150 hotels explained by <b>Stars</b> (1–5), <b>DistanceCentre</b> (km), <b>Rating</b> (0–10, booking site), <b>Satisfaction</b> (0–100, satisfaction survey), <b>Reviews</b> (hundreds of reviews), <b>Spa</b> (1/0), <b>Breakfast</b> (1 = included, 0 = not).</p>${ECO.m2p1.sum}${ECO.m2p1.anova}${ECO.m2p1.coef}${ECO.m2p1.residStars}${ECO.m2p1.pp}`,items:[
 MQ('a1','t5',0.5,'1) Global quality of the model?',[`Very good: adjusted R² = ${M2.adj}`,`Excellent: R² = ${M2.R2} is above 0.8 so the model is perfect`,'Low: SYX is above 20','Medium: R is below 0.95'],0,`<p>Adjusted R² ${M2.adj}: ${qual(M2.adj)}.</p>`),
 MW('a2','t8',1.5,'<p>2) Define multicollinearity. Do you detect it here? What should be done?</p>',[{c:'Definition: independent variables strongly correlated / redundant',pts:0.5},{c:'Detected with the VIF: Rating (≈ 18.2) and Satisfaction (≈ 17.2) are above 5',pts:0.5},{c:'Remove one variable at a time, starting with the most redundant (Rating, highest VIF), then check again',pts:0.5}],`<p>Rating (VIF ${M2.vif.Rating}) and Satisfaction (VIF ${M2.vif.Satisfaction}) measure nearly the same thing. Remove the most redundant first (Rating), rerun, check the VIFs; never remove both at once. Note the unexpected negative sign of Satisfaction: a classic symptom.</p>`,6),
 MQ('a3','t6',1,'3) Read the residual plot for Stars. Which problem do you detect?',['Heteroscedasticity: the dispersion of residuals grows with the number of stars (conic shape)','Linearity: the residuals follow a U shape','None: residuals are centred on 0','Normality: the stars are not normally distributed'],0,'<p>The spread is small for 1-star hotels and large for 5-star hotels: unequal variance.</p>'),
 MW('a4','t6',1,'<p>4) What are the practical consequences of heteroscedasticity for this model? Can the estimated coefficients still be used?</p>',[{c:'The estimated coefficients remain usable (not biased)',pts:0.5},{c:'Standard errors are wrong: confidence intervals and significance tests can no longer be trusted',pts:0.5}],'<p>The slope estimates stay usable, but the standard errors are not reliable: t tests, F test and confidence intervals cannot be used as such. Look for a missing variable or change the shape of the model.</p>',4),
 {id:'a5',topic:'t7',type:'case',pts:1,title:'5) Global significance',q:'<p>Ignoring the previous problems, is the model globally significant?</p>',parts:[
  MP('Test and hypotheses',0.5,['F test: H0: all seven β = 0; H1: at least one β ≠ 0','F test: H0: no effect; H1: effect (without coefficients)','t test on Stars','Levene’s test'],0),
  MP('Conclusion',0.5,['Sig. < .001: reject H0, at least one variable influences the price','Fail to reject H0','The model is perfect','Cannot conclude because of multicollinearity'],0)],solution:`<p>F = ${M2.F}, Sig. &lt; .001.</p>`},
 {id:'a6',topic:'t7',type:'case',pts:1,title:'6) Breakfast',q:'<p>Does including breakfast have a significant effect on the price?</p>',parts:[
  MP('Hypotheses',0.5,['H0: βBreakfast = 0; H1: βBreakfast ≠ 0','H0: βBreakfast ≠ 0; H1: βBreakfast = 0','H0: all β = 0','H0: Breakfast and Spa are independent'],0),
  MP('Conclusion',0.5,[`Sig. = ${pv(M2.p.Breakfast)} > 0.05: no significant effect; the coefficient (−0.633) is not interpreted`,'Breakfast lowers the price by 0.633 €','Significant because the CI is wide','Significant at 10%'],0)],solution:`<p>p = ${pv(M2.p.Breakfast)}; the CI [${M2.lo.Breakfast}; ${M2.hi.Breakfast}] contains 0.</p>`},
 MQ('a7','t5',1,`7) Interpret the coefficient of DistanceCentre (${P2.DistanceCentre}).`,[`Each extra km from the centre lowers the price by about ${Math.abs(P2.DistanceCentre)} € per night on average, everything else remaining the same`,`Hotels are ${Math.abs(P2.DistanceCentre)} km from the centre on average`,`The price falls by ${Math.abs(P2.DistanceCentre)}% per km`,'Distance has no effect because the sign is negative'],0,'<p>Significant (Sig. &lt; .001), negative effect.</p>'),
 MQ('a8','t7',1,'8) Interpret the 95% confidence interval of Reviews.',[`We are 95% confident that 100 more reviews raise the price by between ${M2.lo.Reviews} and ${M2.hi.Reviews} € per night, everything else the same`,`One more review raises the price by between ${M2.lo.Reviews} and ${M2.hi.Reviews} €`,`95% of hotels have between ${M2.lo.Reviews} and ${M2.hi.Reviews} hundred reviews`,'The variable is not significant'],0,'<p>Mind the unit: Reviews is in hundreds.</p>'),
 MQ('a9','t5',1,'9) Which equation describes the model in the population?',['Pricei = β0 + β1 Starsi + β2 DistanceCentrei + … + β7 Breakfasti + εi','Price^i = b0 + b1 Starsi + … + b7 Breakfasti + εi','Pricei = 35.745 + 23.430 Starsi + …','Pricei = β0 + Starsi + DistanceCentrei + … + εi'],0,'<p>Population: Greek β and the error ε. The estimated equation uses b and has no error when written with Ŷ.</p>'),
 MQ('a10','t5',1,'10) Can you predict the price of a 5-star hotel located 25 km from the centre?',['No: 25 km is outside the data range (0.2 to 12.2 km); the model is not valid there','Yes, by plugging the values into the equation','Yes, because the model is globally significant','Only with a dummy variable'],0,'<p>A model is only meaningful inside the data interval (2022 final).</p>')]},
{title:'Problem 2 · Tests (4 points)',intro:`${ECO.m2p2.paired}${ECO.m2p2.one}${ECO.m2p2.cross}${ECO.m2p2.chi}${ECO.m2p2.spear}`,items:[
 {id:'b1',topic:'t4',type:'case',pts:1,title:'1) Renovation',q:'<p>64 hotels were rated by the same inspectors before and after a renovation (After, Before). Did the mean grade change?</p>',parts:[
  MP('Test',0.5,['Paired samples t-test','Independent samples t-test','Chi² test','One sample t-test on After only'],0),
  MP('Conclusion',0.5,[`p = ${pv(EK.m2p2.pairedP)} < 0.05: the mean grade changed (it increased by about ${EK.m2p2.pairedM.toFixed(2)})`,'No change: the CI is narrow','Fail to reject H0','The samples are independent'],0)],solution:'<p>Same hotels measured twice → paired.</p>'},
 {id:'b2',topic:'t4',type:'case',pts:1,title:'2) Mean rating equal to 8?',q:'<p>The chain claims its mean rating is 8.</p>',parts:[
  MP('Hypotheses',0.5,['H0: μ = 8; H1: μ ≠ 8','H0: x̄ = 8','H0: μ ≠ 8; H1: μ = 8','H0: μ ≤ 8; H1: μ > 8'],0),
  MP('Conclusion',0.5,[`p = ${pv(EK.m2p2.oneP)} < 0.05: reject H0; the mean rating differs from 8 (it is lower, ≈ ${EK.m2p2.oneM.toFixed(2)})`,'Fail to reject H0','Accept H0','Use a binomial test'],0)],solution:'<p>One sample t-test.</p>'},
 {id:'b3',topic:'t4',type:'case',pts:1,title:'3) Chain and renovation',q:'<p>Are “being part of a chain” and “renovated recently” independent?</p>',parts:[
  MP('Which p-value do you read?',0.5,['Fisher’s exact test: 2 cells have an expected count below 5','Pearson chi-square, because it is significant','Both: average them','Levene'],0),
  MP('Conclusion',0.5,[`Fisher p = ${pv(EK.m2p2.fisher)} > 0.05: fail to reject independence`,`Chi² p = ${pv(EK.m2p2.chiP)}: the variables are dependent`,'The variables are proven independent','No test is possible'],0)],solution:`<p>The χ² would wrongly reject (p = ${pv(EK.m2p2.chiP)}): its assumption fails, so read Fisher.</p>`},
 MQ('b4','t4',1,'4) Stars (1–5) and price per night: which method, and what do you conclude?',[`Spearman correlation (ordinal variable, monotonic link): ρ = ${EK.m2p2.spR.toFixed(3)}, Sig. < .001, strong positive correlation`,'Pearson correlation because both are numbers','Chi² test because stars are qualitative','Two-sample t-test'],0,'<p>2023 final: ordinal + quantitative → Spearman or Kendall; assumption: a monotonic link.</p>')]},
{title:'Problem 3 · Location (2 points)',intro:`<p>Price per night explained by <b>RoomSize</b> (m²) and the location: Suburb (1/0), Airport (1/0); the city centre is the reference.</p>${ECO.m2p3.coef}`,items:[
 MW('c1','t8',1,`<p>1) Interpret the coefficient of Suburb (${M23.b.Suburb}).</p>`,[{c:'Compared with a hotel in the city centre (reference)',pts:0.5},{c:'A suburb hotel is about 26.8 € cheaper per night, room size remaining the same; significant',pts:0.5}],`<p>Compared with the city centre, a suburb hotel is ${Math.abs(M23.b.Suburb)} € cheaper per night, room size remaining the same (Sig. &lt; .001).</p>`,4),
 MN('2) Predicted price of a 30 m² room at an airport hotel.',1,+(M23.b['(Constant)']+M23.b.RoomSize*30+M23.b.Airport).toFixed(2),0.1,'t8')]},
{title:'Problem 4 · What guests expect (4 points)',intro:`<p>300 guests rated the importance of 9 items (0–10). A PCA was run.</p>${ECO.m2p4.cm}${ECO.m2p4.tv}${ECO.m2p4.rc}`,items:[
 MW('d1','t9',1,'<p>1) One variable seems to break an assumption of the PCA. Which one, which assumption, and why?</p>',[{c:'Age: it does not describe what guests expect (identical concept)',pts:0.5},{c:'It forms its own component (component 3, loading ≈ 0.98) unrelated to the other items',pts:0.5}],'<p>Age is not an expectation of guests: the “identical concept” assumption fails. It ends up alone on component 3.</p>',4),
 MQ('d2','t9',1,'2) What can be said about Parking?',['Badly represented (communality ≈ 0.14, loadings below 0.31): it is not related to the components and may be removed in a second step','It is the most important variable','It belongs to component 2 because 0.309 > 0.3','It must be kept because its eigenvalue is above 1'],0,'<p>Communality below 0.5 and no loading above 0.6.</p>'),
 MW('d3','t9',1,'<p>3) Interpret component 2 (variables and signs).</p>',[{c:'CentralLocation and PublicTransport positive (≈ 0.9)',pts:0.5},{c:'PriceSensitivity negative: guests who value a central, connected location care less about price (opposition)',pts:0.5}],'<p>Component 2: central location and public transport (+) vs price sensitivity (−): “location matters more than price”.</p>',4),
 MQ('d4','t9',1,'4) Should a hotel advertise its spa in public-transport ads to reach guests who value public transport?',['No link: Spa and PublicTransport are on different components','Yes: both have high loadings','Yes, they are opposed','Only if Age is removed'],0,'<p>Different components: no link can be concluded.</p>')]}];

/* ===== Mock 3 ===== */
const M3=EK.m3p1,P3=M3.b;
const M3_S=[
{title:'Problem 1 · Used cars (12 points)',intro:`<p>Price (€) of 200 used cars explained by <b>Age</b> (years), <b>Mileage</b> (thousand km), <b>Power</b> (hp), <b>Region</b> (0 = North, 1 = East, 2 = South, 3 = West), <b>Automatic</b> (1 = automatic gearbox, 0 = manual), <b>PreviousOwners</b> (number) and <b>Warranty</b> (1 = warranty included).</p>${ECO.m3p1.sum}${ECO.m3p1.anova}${ECO.m3p1.coef}${ECO.m3p1.residMil}${ECO.m3p1.resid}${ECO.m3p1.pp}`,items:[
 MW('a1','t8',1,'<p>1) Do you detect a problem with the variable Region? What should have been done?</p>',[{c:'Region is qualitative (4 categories) coded 0–3: its coefficient is meaningless',pts:0.5},{c:'Create 3 dummy variables with one region as the reference group',pts:0.5}],'<p>Region is a nominal variable: coded 0, 1, 2, 3 the model treats it as a quantity. Three dummies (e.g. East, South, West, with North as reference) are needed (2023 final).</p>',4),
 MW('a2','t6',2,'<p>2) Do you detect problems with the L.I.N.E. assumptions? For each, say which plot or value you read.</p>',[{c:'Linearity: the residual plot against Mileage shows a curve (U shape): the effect of mileage is not linear',pts:1},{c:'Outliers: a few residuals far from the others in the residual plot against the predicted value',pts:0.5},{c:'Other assumptions discussed with the right tool (P-P plot for normality; no obvious funnel; independence assumed for cross-sectional data)',pts:0.5}],'<p>Residuals vs Mileage: a clear curve → linearity problem (change the shape, e.g. a non-linear term). Residuals vs predicted: two isolated points → outliers. Normality: read the P-P plot (points close to the line except at the tails, where the outliers are). No obvious conic shape; independence is plausible with cars sampled at the same time.</p>',8),
 MQ('a3','t8',1,'3) Is there a multicollinearity problem?',['No: all VIF are close to 1 (below 5)','Yes: Region has a VIF above 1','Yes: R² is below 0.8','We need a correlation matrix'],0,'<p>VIF &gt; 5 is the course’s threshold.</p>'),
 MQ('a4','t5',0.5,'4) In the following questions, assume the problems are corrected. Global quality?',[`Good: adjusted R² = ${M3.adj}`,`Excellent: R = ${Math.sqrt(M3.R2).toFixed(3)}`,'Low: SYX is above 2 000','Very good: F is above 100'],0,`<p>${qual(M3.adj)}.</p>`),
 {id:'a5',topic:'t7',type:'case',pts:1,title:'5) Global significance',q:'',parts:[
  MP('Test and hypotheses',0.5,['F test: H0: β1 = … = β7 = 0; H1: at least one βj ≠ 0','F test: H0: R² = 0','t test: H0: β = 0 for Age','Chi² test'],0),
  MP('Conclusion',0.5,['Sig. < .001: the model is globally significant','Fail to reject H0','The model explains 100%','No conclusion without normality'],0)],solution:`<p>F = ${M3.F}, Sig. &lt; .001.</p>`},
 {id:'a6',topic:'t7',type:'case',pts:1,title:'6) Warranty',q:'<p>Does including a warranty have a significant effect on the price?</p>',parts:[
  MP('Hypotheses',0.5,['H0: βWarranty = 0; H1: βWarranty ≠ 0','H0: βWarranty ≠ 0','H0: the warranty is useless; H1: it is useful','H0: all β = 0'],0),
  MP('Conclusion',0.5,[`Sig. = ${pv(M3.p.Warranty)} < 0.05: significant; a car with a warranty is about ${Math.round(P3.Warranty)} € more expensive than without, everything else the same`,'Not significant','Significant at 1%','Cannot conclude'],0)],solution:`<p>p = ${pv(M3.p.Warranty)}: significant at 5% but not at 1%.</p>`},
 MW('a7','t5',1,`<p>7) Interpret carefully the coefficient of Age (${P3.Age}).</p>`,[{c:'One more year of age lowers the price by about 798 € on average',pts:0.5},{c:'… everything else remaining the same (significant)',pts:0.5}],`<p>If the age of the car increases by one year, the price falls by ${Math.abs(P3.Age)} € on average, everything else remaining the same (Sig. &lt; .001).</p>`,4),
 MQ('a8','t8',1,`8) Interpret the coefficient of Automatic (${P3.Automatic}).`,[`Compared with a manual car (reference), an automatic car is about ${Math.round(P3.Automatic)} € more expensive, everything else the same`,`Automatic cars are ${Math.round(P3.Automatic)} € cheaper`,`An automatic gearbox increases the price by ${P3.Automatic}%`,'Not significant'],0,'<p>Dummy: always compare with the reference group.</p>'),
 MQ('a9','t5',0.5,`9) Interpret the standard error of the estimate (${M3.syx}).`,[`The average distance between observed and predicted prices is about ${Math.round(M3.syx)} €; small compared with car prices of several thousand euros, but the scale must be known`,`The price of a car is known to within exactly ${Math.round(M3.syx)} €`,`${M3.syx}% of the variance is unexplained`,'The standard deviation of Age'],0,'<p>SYX: average dispersion around the regression line.</p>'),
 MQ('a10','t7',1,`10) What can be said about PreviousOwners (b = ${P3.PreviousOwners})?`,[`No significant effect (Sig. = ${pv(M3.p.PreviousOwners)}): the coefficient is not interpreted`,'Each previous owner lowers the price by 28.9 €','It is significant because its VIF is low','It should be interpreted as a dummy'],0,'<p>The CI contains 0.</p>'),
 MQ('a11','t7',1,'11) Interpret the 95% confidence interval of Power.',[`We are 95% confident that one more horsepower raises the price by between ${M3.lo.Power} and ${M3.hi.Power} €, everything else the same`,`95% of cars have between ${M3.lo.Power} and ${M3.hi.Power} hp`,`Power explains between ${M3.lo.Power}% and ${M3.hi.Power}% of the price`,'The interval proves causality'],0,''),
 MW('a12','t8',1,'<p>12) The residual plot shows two outliers. What can be done if you are not allowed to remove rows from the dataset?</p>',[{c:'Look for errors in the data (e.g. a typo in the price) and correct them',pts:0.5},{c:'Look for a missing explicative variable that would explain those unexpected prices (expected answer), or check non-linearity',pts:0.5}],'<p>2023 final: look for errors; find new explanatory variables (expected answer); imputation by the mean was accepted but not expected.</p>',4)]},
{title:'Problem 2 · Choosing tests (2 points)',intro:'<p>A dataset of 200 resorts: price per night (€, 110–4 000), location (Europe / Japan), sea (0 = close to the sea, 1 = not), feedback (ordinal, 10 categories from “poor” to “perfect”).</p>',items:[
 MQ('b1','t4',1,'1) Which test checks whether the price is related to the feedback? Is an assumption needed?',['Spearman or Kendall correlation; check that the link looks monotonic','Pearson correlation; no assumption','Chi² test; at least 5 per cell','Two-sample t-test; equal variances'],0,'<p>2023 final: one quantitative and one ordinal variable.</p>'),
 MQ('b2','t4',1,'2) Which test checks whether the proportion of resorts close to the sea is the same in Europe and Japan? Assumption?',['Chi² test; check that the expected counts are at least 5 per cell (otherwise Fisher)','Binomial test; none','Two-sample t-test; n > 50','Pearson correlation; linearity'],0,'<p>Comparing proportions in two groups = χ² test.</p>')]},
{title:'Problem 3 · Online electronics shop (6 points)',intro:`<p>800 customers rated their interest in 10 items (0–100). A PCA was run. A and B are two prospects placed on the component plot.</p>${ECO.m3p3.tv}${ECO.m3p3.rc}${ECO.m3p3.plot}`,items:[
 MQ('d1','t9',1,'1) How many dimensions do you keep, and with which tool?',[`${EK.m3p3.keep}, by Kaiser’s rule (eigenvalue > 1); the 4th is only just above 1 and contains a single variable`,'2, because the plot has two axes','10, one per variable','3, because 74% is enough'],0,`<p>Eigenvalues: ${EK.m3p3.values.slice(0,5).join(', ')}…</p>`),
 MW('d2','t9',1.5,'<p>2) Interpret carefully components 1 and 2 (variables, signs) and name them.</p>',[{c:'Component 1: Gaming, Streaming, TechNews positive; PaperBooks negative (opposition)',pts:0.5},{c:'Component 2: PriceComparison and Coupons positive; BrandLoyalty negative',pts:0.5},{c:'Meaningful names (e.g. “digital entertainment vs paper”, “bargain hunters vs brand loyal”)',pts:0.5}],'<p>Component 1: gaming, streaming and tech news (+) against paper books (−). Component 2: price comparison and coupons (+) against brand loyalty (−).</p>',6),
 MQ('d3','t9',0.5,'3) CityPopulation forms a component on its own. What does it mean?',['It is not related to the other variables (a family of one variable); it does not belong to the same concept and could be removed','It is the most important variable','It is correlated with Gaming','The PCA is invalid'],0,'<p>A variable unrelated to the others ends up alone.</p>'),
 MQ('d4','t9',1,'4) Is it a good idea to promote coupons in gaming communities to reach coupon users?',['No: Coupons and Gaming are on different components, no link can be concluded','Yes: both have high loadings','Yes: they are opposed','Only for prospect B'],0,''),
 MQ('d5','t9',0.5,'5) Relationship between BrandLoyalty and Coupons?',['Opposition: same component, opposite signs','No link','They go together','Cannot be read'],0,''),
 MW('d6','t9',1.5,'<p>6) Describe prospects A and B.</p>',[{c:'A (top right): into gaming, streaming and tech news, not paper books; compares prices, uses coupons, little brand loyalty',pts:0.75},{c:'B (bottom left): reads paper books rather than gaming; brand loyal, does not hunt coupons',pts:0.75}],'<p>Describe each prospect only with components 1 and 2, including the variables on the negative side.</p>',6)]}];

const MOCKS=[
 {id:'m1',title:'Mock exam 1 · Foundation',exam:'final',scope:'Chapters 3–5',duration:120,total:20,calculator:MCALC,intro:MOCK_INTRO,summary:'Level 1: a clean regression, four classic tests, a missing SSE cell and a clear PCA.',sections:M1_S},
 {id:'m2',title:'Mock exam 2 · Intermediate',exam:'final',scope:'Chapters 3–5',duration:120,total:20,calculator:MCALC,intro:MOCK_INTRO,summary:'Level 2: multicollinearity, heteroscedasticity, Fisher instead of χ², a three-category dummy, PCA assumptions.',sections:M2_S},
 {id:'m3',title:'Mock exam 3 · Advanced',exam:'final',scope:'Chapters 3–5',duration:120,total:20,calculator:MCALC,intro:MOCK_INTRO,summary:'Level 3 (2023 and 2025 style): a coded qualitative variable, non-linearity and outliers, test choice, a PCA with negative loadings and prospects.',sections:M3_S}];

// numeric items written without an id get one from their position
MOCKS.forEach(m=>m.sections.forEach((s,si)=>s.items.forEach((x,i)=>{if(!x.id)x.id='p'+(si+1)+'n'+(i+1)})));
// MCQ options are written with the right answer first: shuffle them once, deterministically (seeded by the id).
const seed=s=>{let h=2166136261;for(const ch of s){h^=ch.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0};
const mix=(x,key)=>{if(!x||x.type&&x.type!=='mcq'||!Array.isArray(x.o))return;let r=seed(key);const rnd=()=>{r=(Math.imul(r,1103515245)+12345)>>>0;return r/4294967296};
  const idx=x.o.map((_,i)=>i);for(let i=idx.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]]}
  const pos=i=>idx.indexOf(i);x.a=Array.isArray(x.a)?x.a.map(pos).sort((p,q)=>p-q):pos(x.a);x.o=idx.map(i=>x.o[i])};
QUIZ.forEach(q=>mix(q,q.id));
EXERCISES.forEach(x=>{mix(x,x.id);(x.parts||[]).forEach((p,i)=>mix(p,x.id+'-'+i))});
MOCKS.forEach(m=>m.sections.forEach(s=>s.items.forEach(x=>{mix(x,m.id+x.id);(x.parts||[]).forEach((p,i)=>mix(p,m.id+x.id+'-'+i))})));

